<?php require_once __DIR__ . '/functions.php'; require_admin(); $id=isset($_GET['id']) ? (int)$_GET['id'] : 0; $editing=$id > 0; $user=['username'=>'','password'=>'','role'=>'staff']; $selectedSuppliers=[]; if($editing){ $stmt=$conn->prepare('SELECT * FROM users WHERE id = ? LIMIT 1'); $stmt->bind_param('i',$id); $stmt->execute(); $result=$stmt->get_result(); if($result->num_rows>0){ $user=$result->fetch_assoc(); $user['password']=''; } $supplierStmt=$conn->prepare('SELECT supplier_id FROM user_supplier_access WHERE user_id = ?'); $supplierStmt->bind_param('i',$id); $supplierStmt->execute(); $supplierResult=$supplierStmt->get_result(); while($row=$supplierResult->fetch_assoc()){ $selectedSuppliers[]=(int)$row['supplier_id']; } } if(isset($_POST['save'])){ $username=trim($_POST['username'] ?? ''); $password=trim($_POST['password'] ?? ''); $role='staff'; $suppliers=$_POST['suppliers'] ?? []; $displayName=$username; if($editing){ if($password !== ''){ $passwordHash=password_hash($password, PASSWORD_DEFAULT); $stmt=$conn->prepare('UPDATE users SET name = ?, username = ?, password = ?, role = ? WHERE id = ?'); $stmt->bind_param('ssssi',$displayName,$username,$passwordHash,$role,$id); } else { $stmt=$conn->prepare('UPDATE users SET name = ?, username = ?, role = ? WHERE id = ?'); $stmt->bind_param('sssi',$displayName,$username,$role,$id); } $stmt->execute(); $deleteStmt=$conn->prepare('DELETE FROM user_supplier_access WHERE user_id = ?'); $deleteStmt->bind_param('i',$id); $deleteStmt->execute(); foreach($suppliers as $supplierId){ $supplierId=(int)$supplierId; $insertStmt=$conn->prepare('INSERT INTO user_supplier_access(user_id, supplier_id) VALUES (?, ?)'); $insertStmt->bind_param('ii',$id,$supplierId); $insertStmt->execute(); } } else { $passwordHash=password_hash($password, PASSWORD_DEFAULT); $stmt=$conn->prepare('INSERT INTO users(name, username, password, role) VALUES (?, ?, ?, ?)'); $stmt->bind_param('ssss',$displayName,$username,$passwordHash,$role); $stmt->execute(); $newId=$conn->insert_id; foreach($suppliers as $supplierId){ $supplierId=(int)$supplierId; $insertStmt=$conn->prepare('INSERT INTO user_supplier_access(user_id, supplier_id) VALUES (?, ?)'); $insertStmt->bind_param('ii',$newId,$supplierId); $insertStmt->execute(); } } header('Location: users.php'); exit; } $suppliers=$conn->query('SELECT * FROM suppliers ORDER BY supplier_name ASC'); $pageTitle=$editing ? 'Edit User' : 'Create User'; include __DIR__ . '/partials/header.php'; ?><section class='card'><div class='section-head'><h2><?= $editing ? 'Edit User' : 'Create User' ?></h2><p>Set login details and supplier access.</p></div><form method='post' class='form-grid'><div><label class='field-label'>Username</label><input type='text' name='username' value='<?= esc($user['username']) ?>' placeholder='Username' required></div><div><label class='field-label'>Password</label><input type='password' name='password' value='' placeholder='<?= $editing ? 'Leave blank to keep current password' : 'Password' ?>' <?= $editing ? '' : 'required' ?>></div><div class='full'><label class='field-label'>Supplier Access</label><div class='chips-grid'><?php while($supplier=$suppliers->fetch_assoc()): ?><?php $supplierId=(int)$supplier['id']; ?><label class='chip-item'><input type='checkbox' name='suppliers[]' value='<?= $supplierId ?>' <?= in_array($supplierId,$selectedSuppliers,true) ? 'checked' : '' ?>><span><?= esc($supplier['supplier_name']) ?></span></label><?php endwhile; ?></div></div><div class='full action-row'><button class='btn btn-dark' name='save'>Save User</button><a class='btn btn-outline' href='users.php'>Back</a></div></form></section><?php include __DIR__ . '/partials/footer.php'; ?>
